def refs_for(body):
    low = body.lower(); out = []
    for key, kws, n in RULES:
        if sum(low.count(k) for k in kws) >= n:
            out += SRC[key]
    seen = set(); res = []
    for t, u in out:
        if u not in seen:
            seen.add(u); res.append((t, u))
    return res[:6]


def refs_md(body):
    r = refs_for(body)
    lines = ['', '## Nguồn tham khảo', '',
             'Bài viết do Ban biên tập QHUB HERBAL biên soạn, đối chiếu với hướng dẫn và tài liệu của các tổ chức y tế uy tín dưới đây; phần quan niệm phương Đông được tổng hợp từ tài liệu thảo mộc truyền thống. Thông tin chỉ mang tính tham khảo, không thay thế chẩn đoán và tư vấn của bác sĩ.', '']
    if r:
        lines += [f'- [{t}]({u})' for t, u in r]
    else:
        return ''
    return '\n'.join(lines) + '\n'
